/**
 * Per-theme loudness normalisation. Every song is trimmed so that it plays at TARGET_LUFS
 * (integrated, ITU-R BS.1770, at the game's default volume settings) ± a small per-theme offset —
 * so walking from the beach into the mine or from a summer song into a winter one never jumps.
 *
 * MEASURED_LUFS is generated by `node scripts/audio-render.mjs --calibrate` (it renders each theme's
 * first 60 s through the real mixer and stores the level the song would have *without* this trim);
 * re-run it after changing an arrangement, instrument or mix.
 */
export const TARGET_LUFS = -21;

/** Deliberate offsets from the target (LU): the mine and the nights sit a little under the day. */
export const TARGET_OFFSET: Record<string, number> = {
  mine: -1, 'mine-ice': -1, 'mine-lava': -1,
  night: -0.8, 'night-spring': -0.8, 'night-fall': -0.8, 'night-winter': -0.8,
  rain: -0.5,
};

// @generated-begin (scripts/audio-render.mjs --calibrate)
export const MEASURED_LUFS: Record<string, number> = {
  'beach': -22.6,
  'fall': -19.4,
  'fall-2': -23.9,
  'fall-3': -24.6,
  'festival': -22.4,
  'festival-blossom': -23.7,
  'festival-harvest': -22,
  'festival-starfall': -23.8,
  'festival-tide': -20.8,
  'forest': -24.9,
  'inn': -23.6,
  'mine': -29.7,
  'mine-ice': -27.7,
  'mine-lava': -30.1,
  'night': -27.4,
  'night-fall': -22.8,
  'night-spring': -23.8,
  'night-winter': -23,
  'rain': -27.5,
  'spring': -22.7,
  'spring-2': -21.1,
  'spring-3': -21.5,
  'summer': -20,
  'summer-2': -23.6,
  'summer-3': -24.3,
  'title': -22.8,
  'town': -22.4,
  'winter': -21.3,
  'winter-2': -22.3,
  'winter-3': -21.7,
};
// @generated-end

/** Linear gain that brings theme `id` to its target (1 when it has not been measured yet). */
export function loudnessTrim(id: string): number {
  const m = MEASURED_LUFS[id];
  if (m === undefined || !Number.isFinite(m)) return 1;
  const target = TARGET_LUFS + (TARGET_OFFSET[id] ?? 0);
  return Math.max(0.2, Math.min(5, Math.pow(10, (target - m) / 20)));
}
